content.text:
{
  "name": "通用控制台通信接口",
  "name_en": "Generic Console Communication Interface",
  "manufacturer": "",
  "description": "这是一个通用的控制台式通信接口，用于在实验室中通过文本命令或流式数据通道与仪器进行交互。它适合管理读写通信会话，例如启动、停止、关闭连接，以及处理输入输出数据流。",
  "description_en": "This is a generic console-style communication interface used in laboratories to interact with instruments through text commands or streaming data channels. It is suited for managing read/write communication sessions, including starting, stopping, closing connections, and handling input/output data streams.",
  "actions": [
    {
      "action_name": "auto-start",
      "description": "启动通信会话。",
      "description_en": "Start the communication session."
    },
    {
      "action_name": "auto-stop",
      "description": "停止通信会话。",
      "description_en": "Stop the communication session."
    },
    {
      "action_name": "auto-join",
      "description": "等待通信任务结束。",
      "description_en": "Wait for the communication task to finish."
    },
    {
      "action_name": "auto-close",
      "description": "关闭通信连接。",
      "description_en": "Close the communication connection."
    },
    {
      "action_name": "auto-reader",
      "description": "读取输入通信数据流。",
      "description_en": "Read the incoming communication data stream."
    },
    {
      "action_name": "auto-writer",
      "description": "写入输出通信数据流。",
      "description_en": "Write to the outgoing communication data stream."
    }
  ],
  "tag_hints": [
    "console communication",
    "instrument I/O",
    "streaming read/write",
    "text command interface",
    "serial-style communication",
    "lab instrument control"
  ]
}

